create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text not null,member_type text not null default 'Student' check(member_type in ('Student','Alumni','Staff','Friend')),class_year text,profession text,location text,bio text,avatar_url text,is_verified boolean not null default false,is_directory_visible boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,member_type) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','OMBACIAN'),coalesce(new.raw_user_meta_data->>'member_type','Student')) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create table if not exists public.announcements(id bigint generated always as identity primary key,title text not null,content text not null,is_pinned boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.events(id bigint generated always as identity primary key,title text not null,description text,event_date timestamptz not null,location text,created_at timestamptz not null default now());
create table if not exists public.event_rsvps(id bigint generated always as identity primary key,event_id bigint not null references public.events(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'going' check(status in ('going','interested','not_going')),created_at timestamptz not null default now(),unique(event_id,user_id));
create table if not exists public.messages(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 2000),created_at timestamptz not null default now());
create table if not exists public.memories(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,title text not null,caption text,image_url text,memory_date date,is_approved boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.reports(id bigint generated always as identity primary key,reporter_id uuid references public.profiles(id) on delete set null,target_type text not null,target_id text not null,reason text not null,status text not null default 'open',created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.announcements enable row level security;alter table public.events enable row level security;alter table public.event_rsvps enable row level security;alter table public.messages enable row level security;alter table public.memories enable row level security;alter table public.reports enable row level security;
create policy "Authenticated members view visible profiles" on public.profiles for select to authenticated using(is_directory_visible=true or auth.uid()=id);
create policy "Members update their own profile" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "Anyone reads announcements" on public.announcements for select using(true);
create policy "Anyone reads events" on public.events for select using(true);
create policy "Members read RSVPs" on public.event_rsvps for select to authenticated using(true);
create policy "Members create own RSVP" on public.event_rsvps for insert to authenticated with check(auth.uid()=user_id);
create policy "Members update own RSVP" on public.event_rsvps for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Members read chat" on public.messages for select to authenticated using(true);
create policy "Members send own messages" on public.messages for insert to authenticated with check(auth.uid()=user_id);
create policy "Anyone reads approved memories" on public.memories for select using(is_approved=true or auth.uid()=user_id);
create policy "Members submit memories" on public.memories for insert to authenticated with check(auth.uid()=user_id);
create policy "Members create reports" on public.reports for insert to authenticated with check(auth.uid()=reporter_id);
insert into storage.buckets(id,name,public) values('memories','memories',true) on conflict(id) do nothing;
create policy "Public reads memory images" on storage.objects for select using(bucket_id='memories');
create policy "Members upload their own memory images" on storage.objects for insert to authenticated with check(bucket_id='memories' and (storage.foldername(name))[1]=auth.uid()::text);
insert into public.announcements(title,content,is_pinned) select 'Welcome to OMBACIANS','Welcome to the digital community connecting generations of ST JOSEPH''S COLLEGE OMBACI.',true where not exists(select 1 from public.announcements);